// Normalize IndiaMART Push API payload (single lead or array)
const out = [];
const typeMap = { W: 'Direct Enquiry', B: 'Buy Lead', P: 'PNS Call', BIZ: 'Catalog Enquiry', WA: 'WhatsApp Enquiry' };
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const r = b.RESPONSE || b;
  const list = Array.isArray(r) ? r : [r];
  for (const l of list) {
    if (!l || (!l.SENDER_MOBILE && !l.SENDER_EMAIL && !l.SENDER_NAME)) continue;
    out.push({ json: {
      source: 'IndiaMART',
      lead_id: String(l.UNIQUE_QUERY_ID || ''),
      lead_type: typeMap[l.QUERY_TYPE] || l.QUERY_TYPE || '',
      name: l.SENDER_NAME || '',
      phone_raw: l.SENDER_MOBILE || l.SENDER_PHONE || '',
      alt_phone_raw: l.SENDER_MOBILE_ALT || l.SENDER_PHONE_ALT || '',
      email: l.SENDER_EMAIL || '',
      company: l.SENDER_COMPANY || '',
      city: l.SENDER_CITY || '',
      state: l.SENDER_STATE || '',
      pincode: l.SENDER_PINCODE || '',
      address: l.SENDER_ADDRESS || '',
      product: l.QUERY_PRODUCT_NAME || l.QUERY_MCAT_NAME || '',
      category: l.QUERY_MCAT_NAME || '',
      subject: l.SUBJECT || '',
      message: String(l.QUERY_MESSAGE || '').replace(/<br\s*\/?>/gi, '\n').trim(),
      received_at: l.QUERY_TIME || new Date().toISOString()
    }});
  }
}
return out;

// Normalize JustDial lead push (works for GET query params or POST body)
const out = [];
for (const item of $input.all()) {
  const q = { ...(item.json.query || {}), ...(typeof item.json.body === 'object' ? item.json.body : {}) };
  if (!q.mobile && !q.phone && !q.email && !q.name) continue;
  const fullName = [q.prefix, q.name].filter(Boolean).join(' ').trim();
  out.push({ json: {
    source: 'JustDial',
    lead_id: String(q.leadid || q.lead_id || ''),
    lead_type: q.leadtype || '',
    name: fullName,
    phone_raw: q.mobile || q.phone || '',
    alt_phone_raw: q.phone && q.mobile ? q.phone : '',
    email: q.email || '',
    company: q.company || '',
    city: q.city || '',
    state: '',
    pincode: q.pincode || q.branchpin || '',
    address: [q.area, q.brancharea].filter(Boolean).join(', '),
    product: q.category || '',
    category: q.category || '',
    subject: q.category ? `Enquiry for ${q.category}` : 'JustDial enquiry',
    message: q.message || q.requirement || '',
    received_at: [q.date, q.time].filter(Boolean).join(' ') || new Date().toISOString()
  }});
}
return out;

// Clean phone numbers (India), split name, build dedupe key
const toE164 = (raw) => {
  let d = String(raw || '').replace(/\D/g, '');
  if (!d) return '';
  d = d.replace(/^0+/, '');
  if (d.length === 10) d = '91' + d;
  return d.length >= 11 ? d : '';
};
const out = [];
for (const item of $input.all()) {
  const l = item.json;
  const phone = toE164(l.phone_raw) || toE164(l.alt_phone_raw);
  const email = String(l.email || '').trim().toLowerCase();
  if (!phone && !email) continue; // unusable lead
  const name = String(l.name || '').replace(/\s+/g, ' ').trim() || 'there';
  const parts = name.split(' ');
  out.push({ json: {
    ...l,
    name,
    first_name: parts[0],
    last_name: parts.slice(1).join(' '),
    email,
    phone_wa: phone,                  // WATI format: 919876543210
    phone_e164: phone ? '+' + phone : '', // GHL format: +1234567890
    dedupe_key: `${l.source}:${l.lead_id || phone || email}`
  }});
}
return out;

