// Merge AI output with lead + build GHL / WATI payloads
const lead = $('Set Business Config').item.json;
let ai = $json.message?.content ?? $json.content ?? {};
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai.replace(/```json|```/g, '').trim()); } catch (e) { ai = {}; }
}
const tiers = ['HOT', 'WARM', 'COLD', 'SPAM'];
const tier = tiers.includes(String(ai.tier || '').toUpperCase()) ? String(ai.tier).toUpperCase() : 'WARM';
const score = Math.max(0, Math.min(100, Number(ai.score) || 50));
const stageMap = { HOT: lead.ghl_stage_hot, WARM: lead.ghl_stage_warm, COLD: lead.ghl_stage_cold, SPAM: lead.ghl_stage_cold };
const product = ai.product_requested || lead.product || 'your requirement';

// WhatsApp template params cannot contain newlines / 4+ spaces
const clean = (s, max) => String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, max);
const waMessage = clean(ai.whatsapp_reply || `Our team will share details and pricing shortly. Could you confirm the quantity you need?`, 600);

const tags = ['ai-qualified', lead.source.toLowerCase(), `tier-${tier.toLowerCase()}`];
if (lead.lead_type) tags.push(lead.lead_type.toLowerCase().replace(/\s+/g, '-'));

const note = [
  `🤖 AI Lead Qualification — ${lead.source}`,
  `Tier: ${tier} | Score: ${score}/100`,
  `Intent: ${ai.intent || '-'}`,
  `Product: ${product}`,
  `Quantity: ${ai.quantity || '-'}`,
  `Urgency: ${ai.urgency || '-'}`,
  `Budget signal: ${ai.budget_signal || '-'}`,
  `Est. value (INR): ${ai.estimated_deal_value_inr || '-'}`,
  `Language: ${ai.language || '-'}`,
  `Summary: ${ai.summary || '-'}`,
  `Next best action: ${ai.next_best_action || '-'}`,
  ``,
  `--- Original enquiry ---`,
  `Lead ID: ${lead.lead_id || '-'} | Type: ${lead.lead_type || '-'}`,
  `Subject: ${lead.subject || '-'}`,
  `Message: ${lead.message || '-'}`,
  `Location: ${[lead.address, lead.city, lead.state, lead.pincode].filter(Boolean).join(', ') || '-'}`,
  `Received: ${lead.received_at}`,
  ``,
  `WhatsApp auto-reply: ${waMessage}`
].join('\n');

const contact = {
  locationId: lead.ghl_location_id,
  firstName: lead.first_name,
  lastName: lead.last_name || undefined,
  name: lead.name,
  source: lead.source,
  tags,
  city: lead.city || undefined,
  state: lead.state || undefined,
  postalCode: lead.pincode || undefined,
  address1: lead.address || undefined,
  country: 'IN',
  companyName: lead.company || undefined
};
if (lead.phone_e164) contact.phone = lead.phone_e164;
if (lead.email) contact.email = lead.email;

return { json: {
  ...lead,
  ai_tier: tier,
  ai_score: score,
  ai_summary: ai.summary || '',
  ai_language: ai.language || '',
  wa_message: waMessage,
  ghl_note: note,
  ghl_contact_payload: contact,
  ghl_opportunity_payload: {
    locationId: lead.ghl_location_id,
    pipelineId: lead.ghl_pipeline_id,
    pipelineStageId: stageMap[tier],
    name: clean(`${product} - ${lead.name} (${lead.source})`, 120),
    status: 'open',
    monetaryValue: Number(ai.estimated_deal_value_inr) || 0,
    source: lead.source
  },
  wati_payload: {
    template_name: lead.wati_template_name,
    broadcast_name: `lead_auto_reply_${Date.now()}`,
    parameters: [
      { name: 'name', value: clean(lead.first_name, 60) },
      { name: 'product', value: clean(product, 100) },
      { name: 'message', value: waMessage },
      { name: 'business', value: clean(lead.business_name, 60) }
    ]
  }
}};
